"""
API client utilities.

Port of: src/utils/api.ts

Handles API calls to the Anthropic API.
"""

from __future__ import annotations

import os
from typing import Any, AsyncGenerator, Optional


async def call_api(
    messages: list[dict[str, Any]],
    *,
    model: str,
    system_prompt: str = "",
    tools: list[dict[str, Any]] | None = None,
    max_tokens: int = 16384,
    temperature: float = 1.0,
    stream: bool = True,
) -> AsyncGenerator[dict[str, Any], None]:
    """
    Call the Anthropic API.

    This is a simplified port that uses the anthropic Python SDK.
    In the TS source, this handles streaming, retries, and error handling.
    """
    api_key = os.environ.get("ANTHROPIC_API_KEY", "")
    if not api_key:
        yield {
            "type": "error",
            "error": "ANTHROPIC_API_KEY environment variable is not set.",
        }
        return

    try:
        import anthropic

        client = anthropic.AsyncAnthropic(api_key=api_key)

        # Strip [1m] suffix from model name for API
        from hare.utils.model import normalize_model_string_for_api
        api_model = normalize_model_string_for_api(model)

        kwargs: dict[str, Any] = {
            "model": api_model,
            "max_tokens": max_tokens,
            "messages": messages,
        }

        if system_prompt:
            kwargs["system"] = system_prompt
        if tools:
            kwargs["tools"] = tools

        if stream:
            async with client.messages.stream(**kwargs) as stream_response:
                async for event in stream_response:
                    yield _convert_event(event)

                final_message = await stream_response.get_final_message()
                yield {
                    "type": "message",
                    "message": _convert_message(final_message),
                }
        else:
            message = await client.messages.create(**kwargs)
            yield {
                "type": "message",
                "message": _convert_message(message),
            }

    except ImportError:
        yield {
            "type": "error",
            "error": "anthropic package is not installed. Run: pip install anthropic",
        }
    except Exception as e:
        yield {
            "type": "error",
            "error": str(e),
        }


def _convert_event(event: Any) -> dict[str, Any]:
    """Convert an SDK streaming event to our internal format."""
    return {
        "type": "stream_event",
        "event": event,
    }


def _convert_message(message: Any) -> dict[str, Any]:
    """Convert an SDK message to our internal dict format."""
    content_blocks = []
    for block in message.content:
        if block.type == "text":
            content_blocks.append({"type": "text", "text": block.text})
        elif block.type == "tool_use":
            content_blocks.append({
                "type": "tool_use",
                "id": block.id,
                "name": block.name,
                "input": block.input,
            })

    return {
        "role": "assistant",
        "content": content_blocks,
        "model": message.model,
        "stop_reason": message.stop_reason,
        "usage": {
            "input_tokens": message.usage.input_tokens,
            "output_tokens": message.usage.output_tokens,
        },
    }

utils\\apple_terminal_backup.py:
"""Apple Terminal.app preferences backup/restore (`appleTerminalBackup.ts`)."""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any, Literal, TypedDict

from hare.utils.exec_file_no_throw import exec_file_no_throw
from hare.utils.log import log_error

_state: dict[str, Any] = {"in_progress": False, "backup_path": None}


def _state_path() -> str:
    return os.path.join(os.path.expanduser("~"), ".claude", "apple_terminal_state.json")


def _load_state() -> None:
    global _state
    try:
        with open(_state_path(), encoding="utf-8") as f:
            _state.update(json.load(f))
    except (OSError, json.JSONDecodeError):
        pass


def _save_state() -> None:
    os.makedirs(os.path.dirname(_state_path()), exist_ok=True)
    with open(_state_path(), "w", encoding="utf-8") as f:
        json.dump(_state, f)


def mark_terminal_setup_in_progress(backup_path: str) -> None:
    _load_state()
    _state["in_progress"] = True
    _state["backup_path"] = backup_path
    _save_state()


def mark_terminal_setup_complete() -> None:
    _load_state()
    _state["in_progress"] = False
    _save_state()


def _get_terminal_recovery_info() -> tuple[bool, str | None]:
    _load_state()
    return bool(_state.get("in_progress")), _state.get("backup_path")


def get_terminal_plist_path() -> str:
    return str(Path.home() / "Library" / "Preferences" / "com.apple.Terminal.plist")


async def backup_terminal_preferences() -> str | None:
    terminal_plist_path = get_terminal_plist_path()
    backup_path = f"{terminal_plist_path}.bak"
    try:
        code, _, _ = await exec_file_no_throw("defaults", ["export", "com.apple.Terminal", terminal_plist_path])
        if code != 0:
            return None
        if not os.path.isfile(terminal_plist_path):
            return None
        await exec_file_no_throw("defaults", ["export", "com.apple.Terminal", backup_path])
        mark_terminal_setup_in_progress(backup_path)
        return backup_path
    except Exception as e:
        log_error(e)
        return None


class RestoreRestored(TypedDict):
    status: Literal["restored", "no_backup"]


class RestoreFailed(TypedDict):
    status: Literal["failed"]
    backup_path: str


RestoreResult = RestoreRestored | RestoreFailed


async def check_and_restore_terminal_backup() -> RestoreResult:
    in_progress, backup_path = _get_terminal_recovery_info()
    if not in_progress:
        return {"status": "no_backup"}
    if not backup_path:
        mark_terminal_setup_complete()
        return {"status": "no_backup"}
    if not os.path.isfile(backup_path):
        mark_terminal_setup_complete()
        return {"status": "no_backup"}
    try:
        code, _, _ = await exec_file_no_throw("defaults", ["import", "com.apple.Terminal", backup_path])
        if code != 0:
            return {"status": "failed", "backup_path": backup_path}
        await exec_file_no_throw("killall", ["cfprefsd"])
        mark_terminal_setup_complete()
        return {"status": "restored"}
    except Exception as e:
        log_error(RuntimeError(f"Failed to restore Terminal.app settings: {e}"))
        mark_terminal_setup_complete()
        return {"status": "failed", "backup_path": backup_path}

utils\\argument_substitution.py:
"""Substitute ``$ARGUMENTS`` placeholders in skill prompts (`argumentSubstitution.ts`)."""

from __future__ import annotations

import re
import shlex


def parse_arguments(args: str) -> list[str]:
    if not args or not args.strip():
        return []
    try:
        from hare.utils.bash.shell_quote import ShellParseSuccess, try_parse_shell_command

        result = try_parse_shell_command(args)
        if isinstance(result, ShellParseSuccess):
            return [t for t in result.tokens if isinstance(t, str)]
    except Exception:
        pass
    return [x for x in args.split() if x]


def parse_argument_names(argument_names: str | list[str] | None) -> list[str]:
    if not argument_names:
        return []

    def valid(name: str) -> bool:
        return bool(name.strip()) and not name.isdigit()

    if isinstance(argument_names, list):
        return [n for n in argument_names if valid(str(n))]
    return [n for n in argument_names.split() if valid(n)]


def generate_progressive_argument_hint(arg_names: list[str], typed_args: list[str]) -> str | None:
    remaining = arg_names[len(typed_args) :]
    if not remaining:
        return None
    return " ".join(f"[{n}]" for n in remaining)


def substitute_arguments(
    content: str,
    args: str | None,
    append_if_no_placeholder: bool = True,
    argument_names: list[str] | None = None,
) -> str:
    if args is None:
        return content
    argument_names = argument_names or []
    parsed = parse_arguments(args)
    original = content
    for i, name in enumerate(argument_names):
        if not name:
            continue
        content = re.sub(rf"\${re.escape(name)}(?![\[\w])", parsed[i] if i < len(parsed) else "", content)

    def repl_idx(m: re.Match[str]) -> str:
        idx = int(m.group(1))
        return parsed[idx] if idx < len(parsed) else ""

    content = re.sub(r"\$ARGUMENTS\[(\d+)\]", repl_idx, content)
    content = re.sub(r"\$(\d+)(?!\w)", repl_idx, content)
    content = content.replace("$ARGUMENTS", args)
    if content == original and append_if_no_placeholder and args:
        content = content + f"\n\nARGUMENTS: {args}"
    return content

