    _org_status = {"status": "disabled", "reason": "preference"}
    _update_settings_for_source("userSettings", {"fastMode": None})
    _save_global_config(
        lambda c: {**c, "penguinModeOrgEnabled": False}
        if isinstance(c, dict)
