_GIT_ROOT_NOT_FOUND: Final = object()

_MAX_LRU: Final = 50


def _lru_factory(maxsize: int = _MAX_LRU):
    """Tiny LRU keyed by single string argument (mirrors memoizeWithLRU)."""

    def decorator(fn):
        cache: dict[str, Any] = {}
        order: list[str] = []

        def wrapper(arg: str) -> Any:
            if arg in cache:
                order.remove(arg)
                order.append(arg)
                return cache[arg]
            result = fn(arg)
            cache[arg] = result
            order.append(arg)
            while len(order) > maxsize:
                old = order.pop(0)
                cache.pop(old, None)
            return result

        wrapper.cache = cache  # type: ignore[attr-defined]
        return wrapper

    return decorator


def log_for_diagnostics_no_pii(
