from __future__ import annotations

import json
import os
import random
import time
from typing import Any

from hare.utils.debug import log_for_debugging
from hare.utils.env_utils import is_env_truthy

# Detailed profiling (same env as startup profiler)
DETAILED_PROFILING = is_env_truthy(os.environ.get("CLAUDE_CODE_PROFILE_STARTUP"))

STATSIG_SAMPLE_RATE = 0.05
STATSIG_LOGGING_SAMPLED = os.environ.get("USER_TYPE") == "ant" or random.random() < STATSIG_SAMPLE_RATE
SHOULD_PROFILE = DETAILED_PROFILING or STATSIG_LOGGING_SAMPLED

MARK_PREFIX = "headless_"
_current_turn = -1
_marks: list[tuple[str, float]] = []


def _get_is_non_interactive_session() -> bool:
    try:
        from hare.bootstrap.state import get_is_non_interactive_session  # type: ignore[import-not-found]

        return get_is_non_interactive_session()
    except ImportError:
        return not os.isatty(0)


def log_event(_name: str, _meta: Any) -> None:
    pass


def json_stringify(obj: Any, *_a: Any, **_k: Any) -> str:
    return json.dumps(obj)


def headless_profiler_start_turn() -> None:
    global _current_turn, _marks
    if not _get_is_non_interactive_session() or not SHOULD_PROFILE:
        return
    _current_turn += 1
    _marks.clear()
    _marks.append((f"{MARK_PREFIX}turn_start", time.perf_counter() * 1000))
    if DETAILED_PROFILING:
        log_for_debugging(f"[headlessProfiler] Started turn {_current_turn}")


def headless_profiler_checkpoint(name: str) -> None:
    if not _get_is_non_interactive_session() or not SHOULD_PROFILE:
        return
    _marks.append((f"{MARK_PREFIX}{name}", time.perf_counter() * 1000))
    if DETAILED_PROFILING:
        log_for_debugging(f"[headlessProfiler] Checkpoint: {name}")


def log_headless_profiler_turn() -> None:
    if not _get_is_non_interactive_session() or not SHOULD_PROFILE:
        return
    times: dict[str, float] = {}
    for name, t in _marks:
        times[name[len(MARK_PREFIX) :]] = t
    turn_start = times.get("turn_start")
    if turn_start is None:
        return
    metadata: dict[str, Any] = {"turn_number": _current_turn}
    sm = times.get("system_message_yielded")
    if sm is not None and _current_turn == 0:
        metadata["time_to_system_message_ms"] = round(sm)
    qs = times.get("query_started")
    if qs is not None:
        metadata["time_to_query_start_ms"] = round(qs - turn_start)
    fc = times.get("first_chunk")
    if fc is not None:
        metadata["time_to_first_response_ms"] = round(fc - turn_start)
    ar = times.get("api_request_sent")
    if qs is not None and ar is not None:
        metadata["query_overhead_ms"] = round(ar - qs)
    metadata["checkpoint_count"] = len(_marks)
    ep = os.environ.get("CLAUDE_CODE_ENTRYPOINT")
    if ep:
        metadata["entrypoint"] = ep
    if STATSIG_LOGGING_SAMPLED:
        log_event("tengu_headless_latency", metadata)
    if DETAILED_PROFILING:
        log_for_debugging(f"[headlessProfiler] Turn {_current_turn} metrics: {json_stringify(metadata)}")

utils\\heatmap.py:
"""Terminal activity heatmap — port of `heatmap.ts`."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime, timedelta


@dataclass
class DailyActivity:
    date: str  # YYYY-MM-DD
    message_count: int


@dataclass
class HeatmapOptions:
    terminal_width: int = 80
    show_month_labels: bool = True


def _to_date_string(d: date) -> str:
    return d.isoformat()


@dataclass
class _Percentiles:
    p25: int
    p50: int
    p75: int


def _calculate_percentiles(daily_activity: list[DailyActivity]) -> _Percentiles | None:
    counts = sorted([a.message_count for a in daily_activity if a.message_count > 0])
    if not counts:
        return None
    n = len(counts)
    return _Percentiles(
        p25=counts[int(n * 0.25)],
        p50=counts[int(n * 0.5)],
        p75=counts[int(n * 0.75)],
    )


def _intensity(count: int, p: _Percentiles | None) -> int:
    if count == 0 or not p:
        return 0
    if count >= p.p75:
        return 4
    if count >= p.p50:
        return 3
    if count >= p.p25:
        return 2
    return 1


CLAUDE_ORANGE = "\x1b[38;2;218;117;86m"
GRAY = "\x1b[90m"
RESET = "\x1b[0m"
BLUE = "\x1b[34m"


def _char(intensity: int) -> str:
    if intensity == 0:
        return GRAY + "·" + RESET
    ch = "░▒▓█"[intensity - 1]
    return CLAUDE_ORANGE + ch + RESET


def generate_heatmap(daily_activity: list[DailyActivity], options: HeatmapOptions | None = None) -> str:
    opt = options or HeatmapOptions()
    day_w = 4
    avail = opt.terminal_width - day_w
    width = min(52, max(10, avail))

    activity_map = {a.date: a for a in daily_activity}
    p = _calculate_percentiles(daily_activity)

    today = datetime.now().date()

    def _js_get_day(d: date) -> int:
        return (d.weekday() + 1) % 7  # Sun=0 .. Sat=6 (JS convention)

    current_week_start = today - timedelta(days=_js_get_day(today))
    start = current_week_start - timedelta(weeks=width - 1)

    grid: list[list[str]] = [[""] * width for _ in range(7)]
    month_starts: list[tuple[int, int]] = []
    last_m = -1
    cur = start
    for week in range(width):
        for day in range(7):
            if cur > today:
                grid[day][week] = " "
            else:
                ds = _to_date_string(cur)
                act = activity_map.get(ds)
                if day == 0:
                    m = cur.month
                    if m != last_m:
                        month_starts.append((m - 1, week))
                        last_m = m
                grid[day][week] = _char(_intensity(act.message_count if act else 0, p))
            cur += timedelta(days=1)

    lines: list[str] = []
    if opt.show_month_labels:
        month_names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
        uniq_m = [month_names[m] for m, _ in month_starts]
        lw = max(1, width // max(len(uniq_m), 1))
        labels = "".join(m[:3].ljust(lw) for m in uniq_m)
        lines.append("    " + labels)
    day_labels = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
    for day in range(7):
        label = day_labels[day].ljust(3) if day in (1, 3, 5) else "   "
        lines.append(label + " " + "".join(grid[day]))
    lines.append("")
    legend = "    Less " + " ".join(CLAUDE_ORANGE + c + RESET for c in "░▒▓█") + " More"
    lines.append(legend)
    return "\n".join(lines)

utils\\horizontal_scroll.py:
"""Horizontal tab strip scrolling window (`horizontalScroll.ts`)."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass
class HorizontalScrollWindow:
    start_index: int
    end_index: int
    show_left_arrow: bool
    show_right_arrow: bool


def calculate_horizontal_scroll_window(
    item_widths: list[float],
    available_width: float,
    arrow_width: float,
    selected_idx: int,
    first_item_has_separator: bool = True,
) -> HorizontalScrollWindow:
    total_items = len(item_widths)
    if total_items == 0:
        return HorizontalScrollWindow(0, 0, False, False)

    clamped_selected = max(0, min(selected_idx, total_items - 1))
    total_width = sum(item_widths)
    if total_width <= available_width:
        return HorizontalScrollWindow(0, total_items, False, False)

    cumulative: list[float] = [0.0]
    for w in item_widths:
        cumulative.append(cumulative[-1] + w)

    def range_width(start: int, end: int) -> float:
        base = cumulative[end] - cumulative[start]
        if first_item_has_separator and start > 0:
            return base - 1.0
        return base

    def effective_width(start: int, end: int) -> float:
        w = available_width
        if start > 0:
            w -= arrow_width
        if end < total_items:
            w -= arrow_width
        return w

    start_index = 0
    end_index = 1
    while end_index < total_items and range_width(start_index, end_index + 1) <= effective_width(
        start_index, end_index + 1
    ):
        end_index += 1

    if clamped_selected >= start_index and clamped_selected < end_index:
        return HorizontalScrollWindow(
            start_index,
            end_index,
            start_index > 0,
            end_index < total_items,
        )

    if clamped_selected >= end_index:
        end_index = clamped_selected + 1
        start_index = clamped_selected
        while start_index > 0 and range_width(start_index - 1, end_index) <= effective_width(
            start_index - 1, end_index
        ):
            start_index -= 1
    else:
        start_index = clamped_selected
        end_index = clamped_selected + 1
        while end_index < total_items and range_width(start_index, end_index + 1) <= effective_width(
            start_index, end_index + 1
        ):
            end_index += 1

    return HorizontalScrollWindow(
        start_index,
        end_index,
        start_index > 0,
        end_index < total_items,
    )

