"""
HTTP utilities.

Port of: src/utils/http.ts

HTTP request helpers with proxy support and retry logic.
"""

from __future__ import annotations

import os
import urllib.request
import urllib.error
import json
from typing import Any, Optional


def get_proxy_url() -> Optional[str]:
    """Get proxy URL from environment."""
    return (
        os.environ.get("HTTPS_PROXY")
        or os.environ.get("https_proxy")
        or os.environ.get("HTTP_PROXY")
        or os.environ.get("http_proxy")
    )


def build_proxy_handler() -> Optional[urllib.request.ProxyHandler]:
    """Build a urllib proxy handler if proxy is configured."""
    proxy = get_proxy_url()
    if proxy:
        return urllib.request.ProxyHandler({
            "http": proxy,
            "https": proxy,
        })
    return None


async def fetch_json(
    url: str,
    *,
    headers: Optional[dict[str, str]] = None,
    timeout: float = 30.0,
) -> Any:
    """Fetch JSON from a URL."""
    import asyncio

    def _fetch():
        req = urllib.request.Request(url)
        if headers:
            for k, v in headers.items():
                req.add_header(k, v)
        req.add_header("Accept", "application/json")

        handlers = []
        proxy_handler = build_proxy_handler()
        if proxy_handler:
            handlers.append(proxy_handler)

        opener = urllib.request.build_opener(*handlers)
        resp = opener.open(req, timeout=timeout)
        return json.loads(resp.read().decode("utf-8"))

    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(None, _fetch)


async def fetch_text(
    url: str,
    *,
    headers: Optional[dict[str, str]] = None,
    timeout: float = 30.0,
) -> str:
    """Fetch text content from a URL."""
    import asyncio

    def _fetch():
        req = urllib.request.Request(url)
        if headers:
            for k, v in headers.items():
                req.add_header(k, v)

        handlers = []
        proxy_handler = build_proxy_handler()
        if proxy_handler:
            handlers.append(proxy_handler)

        opener = urllib.request.build_opener(*handlers)
        resp = opener.open(req, timeout=timeout)
        return resp.read().decode("utf-8")

    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(None, _fetch)


def is_url(s: str) -> bool:
    """Check if string is a URL."""
    return s.startswith("http://") or s.startswith("https://")

utils\\ide_path_conversion.py:
"""WSL / Windows IDE path conversion — port of `idePathConversion.ts`."""

from __future__ import annotations

import re
import subprocess
from typing import Protocol


class IDEPathConverter(Protocol):
    def to_local_path(self, ide_path: str) -> str: ...
    def to_ide_path(self, local_path: str) -> str: ...


_WSL_UNC = re.compile(r"^\\\\wsl(?:\.localhost|\$)\\([^\\]+)(.*)$")


class WindowsToWSLConverter:
    def __init__(self, wsl_distro_name: str | None) -> None:
        self._distro = wsl_distro_name

    def to_local_path(self, windows_path: str) -> str:
        if not windows_path:
            return windows_path
        if self._distro:
            m = _WSL_UNC.match(windows_path)
            if m and m.group(1) != self._distro:
                return windows_path
        try:
            return subprocess.run(
                ["wslpath", "-u", windows_path],
                check=True,
                capture_output=True,
                text=True,
                timeout=30,
            ).stdout.strip()
        except (subprocess.CalledProcessError, FileNotFoundError, OSError):
            s = windows_path.replace("\\", "/")
            m2 = re.match(r"^([A-Za-z]):", s)
            if m2:
                letter = m2.group(1).lower()
                return "/mnt/" + letter + s[2:]
            return windows_path

    def to_ide_path(self, wsl_path: str) -> str:
        if not wsl_path:
            return wsl_path
        try:
            return subprocess.run(
                ["wslpath", "-w", wsl_path],
                check=True,
                capture_output=True,
                text=True,
                timeout=30,
            ).stdout.strip()
        except (subprocess.CalledProcessError, FileNotFoundError, OSError):
            return wsl_path


def check_wsl_distro_match(windows_path: str, wsl_distro_name: str) -> bool:
    m = _WSL_UNC.match(windows_path)
    if m:
        return m.group(1) == wsl_distro_name
    return True

