def first_grapheme(text: str) -> str:
    if not text:
        return ""
    if regex_lib is not None:
        m = regex_lib.match(r"\X", text)
        if m:
            return m.group(0)
    return text[0]


def last_grapheme(text: str) -> str:
    if not text:
        return ""
    if regex_lib is not None:
        matches = list(regex_lib.finditer(r"\X", text))
        if matches:
