def get_project_dirs_up_to_home(subdir: str, cwd: str) -> list[str]:
    """Walk parents until git root — simplified stub."""
    dirs: list[str] = []
    cur = Path(cwd).resolve()
    home = Path.home().resolve()
    for _ in range(64):
        cl = cur / ".claude" / subdir
        if cl.is_dir():
            dirs.append(str(cl))
        if cur == home:
            break
        if (cur / ".git").exists():
