from __future__ import annotations

from typing import Any

# WeakMap equivalent: id(msg) -> text cache
_search_cache: dict[int, str] = {}


def renderable_search_text(msg: Any) -> str:
    i = id(msg)
    if i in _search_cache:
        return _search_cache[i]
    raw = _compute_search_text(msg).lower()
    _search_cache[i] = raw
    return raw


def _compute_search_text(msg: Any) -> str:
    mtype = getattr(msg, "type", None)
    if mtype == "user":
        c = msg.message.content
        if isinstance(c, str):
            return c
        if isinstance(c, list):
            parts: list[str] = []
            for b in c:
                if isinstance(b, dict) and b.get("type") == "text":
                    parts.append(str(b.get("text", "")))
            return "\n".join(parts)
    if mtype == "assistant":
        c = msg.message.content
        if isinstance(c, list):
            parts = []
            for b in c:
                if isinstance(b, dict):
                    if b.get("type") == "text":
                        parts.append(str(b.get("text", "")))
                    elif b.get("type") == "tool_use":
                        parts.append(str(b.get("input", "")))
            return "\n".join(parts)
    return ""

utils\\treeify.py:
"""Tree string rendering (port of treeify.ts)."""

from __future__ import annotations

from typing import Any

DEFAULT_BRANCH = "├"
DEFAULT_LAST = "└"
DEFAULT_LINE = "│"


def treeify(obj: dict[str, Any] | str, *, show_values: bool = True) -> str:
    lines: list[str] = []
    visited: set[int] = set()

    def grow(node: Any, prefix: str, is_last: bool, depth: int) -> None:
        if isinstance(node, str):
            lines.append(prefix + node)
            return
        if not show_values or node is None:
            return
        if isinstance(node, dict):
            oid = id(node)
            if oid in visited:
                lines.append(prefix + "[Circular]")
                return
            visited.add(oid)
            items = list(node.items())
            for i, (k, v) in enumerate(items):
                last = i == len(items) - 1
                branch = DEFAULT_LAST if last else DEFAULT_BRANCH
                if isinstance(v, dict):
                    lines.append(f"{prefix}{branch} {k}:")
                    grow(
                        v,
                        prefix + ("   " if last else f"{DEFAULT_LINE}  "),
                        last,
                        depth + 1,
                    )
                else:
                    lines.append(f"{prefix}{branch} {k}: {v!s}")

    if isinstance(obj, dict):
        grow(obj, "", True, 0)
    else:
        lines.append(str(obj))
    return "\n".join(lines)

utils\\truncate.py:
"""Width-aware truncation (port of truncate.ts) — simplified without grapheme splitter."""

from __future__ import annotations


def _width(s: str) -> int:
    try:
        import wcwidth

        return wcwidth.wcswidth(s) or len(s)
    except ImportError:
        return len(s)


def truncate_to_width(text: str, max_width: int) -> str:
    if _width(text) <= max_width:
        return text
    if max_width <= 1:
        return "…"
    w = 0
    out = ""
    for ch in text:
        cw = _width(ch)
        if w + cw > max_width - 1:
            break
        out += ch
        w += cw
    return out + "…"


def truncate_path_middle(path: str, max_length: int) -> str:
    if _width(path) <= max_length:
        return path
    if max_length <= 0:
        return "…"
    if max_length < 5:
        return truncate_to_width(path, max_length)
    last_slash = path.rfind("/")
    filename = path[last_slash:] if last_slash >= 0 else path
    directory = path[:last_slash] if last_slash >= 0 else ""
    if _width(filename) >= max_length - 1:
        return truncate_to_width(path, max_length)
    avail = max_length - 1 - _width(filename)
    if avail <= 0:
        return truncate_to_width(filename, max_length)
    td = truncate_to_width(directory, avail).rstrip("…")
    return td + "…" + filename

