def _parse_shell_quote_stub(
    cmd: str,
    env: dict[str, str | None] | Callable[[str], str | None] | None = None,
) -> list[ParseEntry]:
    """Minimal tokenizer: split on whitespace outside quotes via shlex."""
    del env
    try:
        return shlex.split(cmd, posix=True)
    except ValueError:
        return cmd.split()


